import SwiftUI
struct WidgetProjectCard: View { let project: ArtifactProject; var primaryTitle = "Open"; let onPrimary: () -> Void; var secondaryTitle: String?; var onSecondary: (() -> Void)?; var onDelete: (() -> Void)?
    var body: some View { VStack(alignment: .leading, spacing: 12) { Text(project.artifact.subject?.capitalized ?? "Classroom widget").font(.caption.bold()).foregroundStyle(StudioTheme.accent); Text(project.artifact.title).font(.title3.bold()); Text(project.artifact.summary).foregroundStyle(.secondary).lineLimit(4); if let level = project.artifact.level { Label(level.replacingOccurrences(of: "-", with: " ").capitalized, systemImage: "graduationcap").font(.caption) }; Spacer(); HStack { Button(primaryTitle, action: onPrimary).buttonStyle(.borderedProminent); if let secondaryTitle, let onSecondary { Button(secondaryTitle, action: onSecondary) }; if let onDelete { Button("Delete", role: .destructive, action: onDelete) } } }.padding().frame(maxWidth: .infinity, minHeight: 230, alignment: .leading).studioCard() }
}
